{
  "name": "pi-emphasis",
  "version": "0.2.0",
  "description": "Colored status pills with icons, labeled headings and colored bold for assistant replies in Pi's terminal, with the rules that teach the agent to write them.",
  "license": "MIT",
  "type": "module",
  "keywords": ["pi-package", "pi", "markdown", "terminal", "pills"],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/johnlindquist/pi-emphasis.git"
  },
  "pi": {
    "extensions": ["./index.ts"]
  },
  "files": ["index.ts", "README.md", "LICENSE"],
  "peerDependencies": {
    "@earendil-works/pi-coding-agent": ">=1.5.0 <2"
  },
  "devDependencies": {
    "@earendil-works/pi-coding-agent": "^1.5.0",
    "bun-types": "^1.4.4",
    "typescript": "^5.6.0"
  },
  "scripts": {
    "test": "bun test",
    "typecheck": "tsc --noEmit",
    "check": "tsc --noEmit && bun test"
  }
}
